#' Gravity Model (PPML)
#'
#' 
#' @param data .
#' @param dep .
#' @param covs .
#' @param origin .
#' @param dest .
#' @param timeVar .
#' @param feOrigin .
#' @param feDest .
#' @param fePair .
#' @param feOrigTime .
#' @param feDestTime .
#' @param feTime .
#' @param cluster .
#' @param level .
#' @param showGuide .
#' @param showHelp .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$coef} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$fit} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$coef$asDF}
#'
#' \code{as.data.frame(results$coef)}
#'
#' @export
gravity <- function(
    data,
    dep,
    covs,
    origin,
    dest,
    timeVar,
    feOrigin = TRUE,
    feDest = TRUE,
    fePair = FALSE,
    feOrigTime = FALSE,
    feDestTime = FALSE,
    feTime = FALSE,
    cluster = "robust",
    level = 95,
    showGuide = FALSE,
    showHelp = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("gravity requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(origin)) origin <- jmvcore::resolveQuo(jmvcore::enquo(origin))
    if ( ! missing(dest)) dest <- jmvcore::resolveQuo(jmvcore::enquo(dest))
    if ( ! missing(timeVar)) timeVar <- jmvcore::resolveQuo(jmvcore::enquo(timeVar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(origin), origin, NULL),
            `if`( ! missing(dest), dest, NULL),
            `if`( ! missing(timeVar), timeVar, NULL))


    options <- gravityOptions$new(
        dep = dep,
        covs = covs,
        origin = origin,
        dest = dest,
        timeVar = timeVar,
        feOrigin = feOrigin,
        feDest = feDest,
        fePair = fePair,
        feOrigTime = feOrigTime,
        feDestTime = feDestTime,
        feTime = feTime,
        cluster = cluster,
        level = level,
        showGuide = showGuide,
        showHelp = showHelp)

    analysis <- gravityClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

